public class KCS_KBVSearchTable extends common
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_common">_common</param>
/// <param name = "_fieldNum">_fieldNum</param>
void initFromCommonField(Common _common, fieldId _fieldNum)
{
    DictField       dictField           = new DictField(_common.TableId, _fieldNum);
    DictType        dictPartyId         = new DictType(extendedTypenum(DirPartyRecId));
    DictType        dictContactPersonId = new DictType(extendedTypenum(ContactPersonId));
    fieldId         requestFieldId      = KCS_KBVSearchTable::findFieldRequestId(_common.TableId);
    DictType        dictFirstPosition   = new DictType(extendedTypenum(KCS_KBVTenderFirstPosition));
    ;


    this.SearchTableId  = _common.TableId;
    this.SearchFieldId  = _fieldNum;
    this.SearchValue    = _common.(_fieldNum);

    if (dictField.typeId() == dictPartyId.id())
    {
        this.DirPartyRecId  = _common.(_fieldNum);
        this.DirPartyId     = DirPartyTable::findRec(this.DirPartyRecId).PartyNumber;
        this.SearchValue    = DirPartyTable::findByNum(this.DirPartyId).Name;

    }    

    if (dictField.typeId() == dictContactPersonId.id())
    {
        this.ContactPersonId    = _common.(_fieldNum);
        this.SearchValue        = ContactPerson::find(this.ContactPersonId).personName();
    }

    if (dictField.typeId() == dictFirstPosition.id())
    {
        this.KBVTenderPosition  = _common.(_fieldNum);
        this.SearchValue        = KCS_KBVSearchTable::convertLVNumber(this.SearchValue);
    }

    if (requestFieldId)
    {
        this.KBVRequestID = _common.(requestFieldId);
    }

    this.RefRecId = _common.RecId;                                              
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_tableId">_tabledId</param>
/// <returns>fieldId</returns>
static fieldId findFieldRequestId(TableId _tableId)
{
    DictTable       dictTable           = new DictTable(_tableId);
    DictField       dictField;
    DictType        dictRequestId       = new DictType(extendedTypeNum(KCS_KBVRequestID));
    int             i;
    ;

    for (i=1; i < dictTable.fieldCnt(); i++)
    {
        dictField = new DictField(dictTable.id(), dictTable.fieldCnt2Id(i));

        if (dictField.typeId() == dictRequestId.id())
        {
            return dictField.id();
        }

    }

    return 0;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_LVValue">_LVValue</param>
/// <returns>AVASearchString</returns>
static AVASearchString convertLVNumber(AVASearchString _LVValue)
{
    container       conTmp;
    int             i;
    ;

    conTmp = str2con(_LVValue, '.',false);
    for(i=2; i <= conLen(conTmp);i++)
    {
        conTmp = conpoke(conTmp, i, strfmt('*%1', conpeek(conTmp, i)));
    }
    return Con2Str(conTmp, '.');
}

/// <summary>
/// desiged from AVA
/// </summary>
/// <param name = "_buildingPrjectId">_buildingPrjectId</param>
/// <param name = "_common">_common</param>
/// <param name = "_fieldId">_fieldId</param>
static void setFromCommonField(KCS_KBVBuildingProjectID _buildingPrjectId, common _common, fieldId _fieldId)
{
    KCS_KBVSearchTable  searchTable;
    fieldId             requestFieldId = KCS_KBVSearchTable::findFieldRequestId(_common.TableId);
    ;
    if (!_buildingPrjectId || !_common || !_fieldId)
    {
        return;
    }


    if (requestFieldId)
    {
        searchTable = KCS_KBVSearchTable::findByRequest(_buildingPrjectId, _common.(requestFieldId), _common.TableId, _fieldId, _common.RecId, true);      
    }
    else
    {
        searchTable = KCS_KBVSearchTable::find(_buildingPrjectId, _common.TableId, _fieldId, true);
    }

    searchTable.RefRecId = _common.RecId;                                       

    if (searchTable.RecId)
    {
        searchTable.initFromCommonField(_common, _fieldId);
        ttsbegin;
        searchTable.Update();
        ttscommit;
    }
    else
    {
        searchTable.initValue();
        searchTable.KBVBuildingProjectID = _buildingPrjectId;
        searchTable.initFromCommonField(_common, _fieldId);
        searchTable.insert();

    }

}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_buildingProjecId">_buildingProjecId</param>
/// <param name = "_requestId">_requestId</param>
/// <param name = "_refTableId">_refTableId</param>
/// <param name = "_refFieldId">_refFieldId</param>
/// <param name = "_refRecId">_refRecId</param>
/// <param name = "_forUpdate">_forUpdate</param>
/// <returns>KCS_KBVSearchTable</returns>
static KCS_KBVSearchTable   findByRequest(  KCS_KBVBuildingProjectID    _buildingProjecId,
                                        KCS_KBVRequestID            _requestId,
                                        RefTableId                  _refTableId,
                                        RefFieldId                  _refFieldId,
                                        RefRecId                    _refRecId,                  
                                        boolean                     _forUpdate = false)
{
    KCS_KBVSearchTable searchTable;
    ;

    if (_buildingProjecId && _requestId && _refTableId && _refFieldId)
    {
        if (_forUpdate)
        {
            searchTable.selectForUpdate(_forUpdate);
        }

        select firstonly searchTable
              where searchTable.KBVBuildingProjectID == _buildingProjecId
                &&  searchTable.KBVRequestID    == _requestId
                &&  searchTable.SearchTableId   == _refTableId
                &&  searchTable.SearchFieldId   == _refFieldId
                &&  searchTable.RefRecId        == _refRecId;                      
    }

    return searchTable;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_buildingProjecId">_buildingProjecId</param>
/// <param name = "_refTableId">_refTableId</param>
/// <param name = "_refFieldId">_refFieldId</param>
/// <param name = "_forUpdate">_forUpdate</param>
/// <returns>KCS_KBVSearchTable</returns>
static KCS_KBVSearchTable   find(   KCS_KBVBuildingProjectID    _buildingProjecId,
                                RefTableId                  _refTableId,
                                RefFieldId                  _refFieldId,
                                boolean                     _forUpdate = false)
{
    KCS_KBVSearchTable searchTable;
    ;

    if (_buildingProjecId && _refTableId && _refFieldId)
    {
        if (_forUpdate)
        {
            searchTable.selectForUpdate(_forUpdate);
        }

        select firstonly searchTable
            where searchTable.KBVBuildingProjectID == _buildingProjecId
                        &&  searchTable.SearchTableId   == _refTableId
                        &&  searchTable.SearchFieldId   == _refFieldId;
    }

    return searchTable;
}

/// <summary>
///     getSearchFieldValue
/// </summary>
/// <param name = "_searchValue">_searchValue</param>
/// <param name = "_sqlOperator">_sqlOperator</param>
/// <param name = "_type">_type</param>
/// <returns>str</returns>
static str getSearchFieldValue(AVASearchString _searchValue, AVASqlOperator _sqlOperator, Types _type = Types::String)
{
    str     ret;

    switch (_sqlOperator)
    {
        case AVASqlOperator::First:    
            ret = _searchValue + '*';       
            break;
        case AVASqlOperator::NotLike:
        case AVASqlOperator::Like:     
            ret = '*' + _searchValue + '*'; 
            break;
        case AVASqlOperator::Last:     
            ret = '*' + _searchValue;       
            break;
        default :                      
            ret = _searchValue;             
            break;
    }

    if (_type == Types::String)
    {
        ret = strfmt('"%1"', ret);
    }

    if (_type == Types::Real)
    {
        ret = StrReplace(ret, ',', '.');
    }

    switch (_sqlOperator)
    {
        case AVASqlOperator::LessEqualThan:
            ret = strfmt(' <= %1', ret);        
            break;
        case AVASqlOperator::LessThan:     
            ret = strfmt(' < %1', ret);         
            break;
        case AVASqlOperator::MoreEqualThan:
            ret = strfmt(' >= %1', ret);        
            break;
        case AVASqlOperator::MoreThan:     
            ret = strfmt(' > %1', ret);         
            break;
        case AVASqlOperator::IsNot:        
            ret = strfmt(' != %1', ret);       
            break;
        case AVASqlOperator::First:
        case AVASqlOperator::Last:
        case AVASqlOperator::NotLike:
        case AVASqlOperator::Like:         
            ret = strfmt(' Like %1', ret);     
            break;
        default:                           
            ret = strfmt(' == %1', ret);        
            break;
    }

    return ret;

}
